create extension if not exists pgcrypto;
create type public.user_role as enum ('super_admin','admin','teacher','parent','finance','admissions','principal');
create type public.section_type as enum ('day','boarding');
create type public.program_year as enum ('year_1','year_2');
create type public.evaluation_status as enum ('draft','pending_approval','approved','returned');
create type public.attendance_status as enum ('present','absent','late','excused');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text not null, role public.user_role not null default 'parent', phone text, avatar_url text, created_at timestamptz not null default now());
create table public.academic_years(id uuid primary key default gen_random_uuid(), name text not null unique, starts_on date not null, ends_on date not null, is_current boolean not null default false);
create table public.terms(id uuid primary key default gen_random_uuid(), academic_year_id uuid not null references public.academic_years(id) on delete cascade, name text not null, term_number smallint not null check(term_number between 1 and 3), starts_on date not null, ends_on date not null, unique(academic_year_id,term_number));
create table public.students(id uuid primary key default gen_random_uuid(), admission_no text not null unique, full_name text not null, date_of_birth date, gender text, section public.section_type not null, program_year public.program_year not null, admission_date date not null default current_date, status text not null default 'active', photo_url text, created_at timestamptz not null default now());
create table public.parent_students(parent_id uuid not null references public.profiles(id) on delete cascade, student_id uuid not null references public.students(id) on delete cascade, relationship text, primary key(parent_id,student_id));
create table public.teacher_students(teacher_id uuid not null references public.profiles(id) on delete cascade, student_id uuid not null references public.students(id) on delete cascade, assigned_at timestamptz not null default now(), primary key(teacher_id,student_id));
create table public.quran_surahs(id smallint primary key, name text not null, ayah_count smallint not null);
create table public.memorization_progress(id uuid primary key default gen_random_uuid(), student_id uuid not null references public.students(id) on delete cascade, teacher_id uuid references public.profiles(id), recorded_on date not null default current_date, juz_from smallint, juz_to smallint, surah text, ayah_from smallint, ayah_to smallint, new_memorization boolean not null default true, revision boolean not null default false, tajweed_score numeric(5,2), fluency_score numeric(5,2), accuracy_score numeric(5,2), notes text);
create table public.evaluations(id uuid primary key default gen_random_uuid(), student_id uuid not null references public.students(id) on delete cascade, teacher_id uuid not null references public.profiles(id), term_id uuid not null references public.terms(id), evaluation_number smallint not null check(evaluation_number between 1 and 3), status public.evaluation_status not null default 'draft', score numeric(5,2), juz_from smallint, juz_to smallint, tajweed_score numeric(5,2), fluency_score numeric(5,2), accuracy_score numeric(5,2), teacher_comment text, admin_comment text, submitted_at timestamptz, approved_at timestamptz, approved_by uuid references public.profiles(id), unique(student_id,term_id,evaluation_number));
create table public.attendance_records(id uuid primary key default gen_random_uuid(), student_id uuid not null references public.students(id) on delete cascade, recorded_by uuid not null references public.profiles(id), attendance_date date not null, status public.attendance_status not null, note text, unique(student_id,attendance_date));
create table public.fee_structures(id uuid primary key default gen_random_uuid(), academic_year_id uuid not null references public.academic_years(id), term_id uuid references public.terms(id), section public.section_type not null, name text not null, amount numeric(12,2) not null, due_date date);
create table public.student_fees(id uuid primary key default gen_random_uuid(), student_id uuid not null references public.students(id) on delete cascade, fee_structure_id uuid not null references public.fee_structures(id), amount_due numeric(12,2) not null, amount_paid numeric(12,2) not null default 0);
create table public.payments(id uuid primary key default gen_random_uuid(), student_id uuid not null references public.students(id), amount numeric(12,2) not null, paid_on timestamptz not null default now(), method text, reference text unique, recorded_by uuid references public.profiles(id), notes text);
create table public.admissions(id uuid primary key default gen_random_uuid(), application_no text not null unique, applicant_name text not null, parent_name text not null, parent_phone text, requested_section public.section_type not null, requested_program_year public.program_year not null, status text not null default 'submitted', documents jsonb not null default '[]'::jsonb, notes text, created_at timestamptz not null default now());
create table public.pages(id uuid primary key default gen_random_uuid(), slug text not null unique, title text not null, content jsonb not null default '{}'::jsonb, seo_title text, seo_description text, published boolean not null default false, updated_at timestamptz not null default now());
create table public.homepage_sections(id uuid primary key default gen_random_uuid(), section_key text not null unique, title text, content jsonb not null default '{}'::jsonb, sort_order integer not null default 0, visible boolean not null default true, updated_at timestamptz not null default now());
create table public.site_settings(key text primary key, value jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(), actor_id uuid references public.profiles(id), action text not null, entity_type text not null, entity_id uuid, old_data jsonb, new_data jsonb, created_at timestamptz not null default now());

alter table public.profiles enable row level security; alter table public.students enable row level security; alter table public.parent_students enable row level security; alter table public.teacher_students enable row level security; alter table public.evaluations enable row level security; alter table public.attendance_records enable row level security; alter table public.memorization_progress enable row level security; alter table public.student_fees enable row level security; alter table public.payments enable row level security; alter table public.admissions enable row level security; alter table public.pages enable row level security; alter table public.homepage_sections enable row level security; alter table public.site_settings enable row level security; alter table public.audit_logs enable row level security;
create or replace function public.my_role() returns public.user_role language sql stable security invoker as $$ select role from public.profiles where id=auth.uid() $$;
create policy "public pages read" on public.pages for select to anon,authenticated using (published=true or public.my_role() in ('super_admin','admin','principal'));
create policy "public homepage read" on public.homepage_sections for select to anon,authenticated using (visible=true or public.my_role() in ('super_admin','admin','principal'));
create policy "public site settings read" on public.site_settings for select to anon,authenticated using (key in ('school_name','logo_url','contact','social_links') or public.my_role() in ('super_admin','admin'));
create policy "admins manage pages" on public.pages for all to authenticated using (public.my_role() in ('super_admin','admin')) with check (public.my_role() in ('super_admin','admin'));
create policy "admins manage homepage" on public.homepage_sections for all to authenticated using (public.my_role() in ('super_admin','admin')) with check (public.my_role() in ('super_admin','admin'));
create policy "admins manage settings" on public.site_settings for all to authenticated using (public.my_role() in ('super_admin','admin')) with check (public.my_role() in ('super_admin','admin'));
create policy "parents see own students" on public.students for select to authenticated using (exists(select 1 from public.parent_students ps where ps.student_id=students.id and ps.parent_id=auth.uid()) or public.my_role() in ('super_admin','admin','principal','finance','admissions') or exists(select 1 from public.teacher_students ts where ts.student_id=students.id and ts.teacher_id=auth.uid()));
create policy "teachers see assigned evaluations" on public.evaluations for select to authenticated using (teacher_id=auth.uid() or public.my_role() in ('super_admin','admin','principal') or exists(select 1 from public.parent_students ps where ps.student_id=evaluations.student_id and ps.parent_id=auth.uid()) and status='approved');
create policy "teachers submit evaluations" on public.evaluations for insert to authenticated with check (teacher_id=auth.uid() and public.my_role()='teacher');
create policy "teachers update drafts" on public.evaluations for update to authenticated using (teacher_id=auth.uid() and status in ('draft','returned')) with check (teacher_id=auth.uid());
create policy "admins approve evaluations" on public.evaluations for update to authenticated using (public.my_role() in ('super_admin','admin','principal')) with check (public.my_role() in ('super_admin','admin','principal'));
create policy "parents see own fees" on public.student_fees for select to authenticated using (exists(select 1 from public.parent_students ps where ps.student_id=student_fees.student_id and ps.parent_id=auth.uid()) or public.my_role() in ('super_admin','admin','principal','finance'));
create policy "parents see own payments" on public.payments for select to authenticated using (exists(select 1 from public.parent_students ps where ps.student_id=payments.student_id and ps.parent_id=auth.uid()) or public.my_role() in ('super_admin','admin','principal','finance'));
